<script lang="ts">
 import {untrack} from 'svelte';import type {Target,Cadence} from '$lib/budget/types';import type {Category} from '$lib/types';
 let {target,categories,month,revision,commandKey,draft}:{target?:Target;categories:Category[];month:string;revision:number;commandKey:string;draft?:{categoryId:number;amountCents:number;cadence:Cadence}}=$props();
 let cadence=$state<Cadence>(untrack(()=>target?.cadence??draft?.cadence??'monthly'));
 let behavior=$state<Target['behavior']>(untrack(()=>target?.behavior??'set_aside'));
 const inputAmount=(v:number|undefined)=>v===undefined?'':`${BigInt(v)/100n}.${(BigInt(v)%100n).toString().padStart(2,'0')}`;
</script>
<form method="POST" action={`?/target&month=${month}`} data-budget-command="target" class="target-form">
 <input type="hidden" name="revision" value={revision}/><input type="hidden" name="key" value={`${commandKey}:target:${target?.categoryId??draft?.categoryId??'new'}`}/><input type="hidden" name="target_id" value={target?.id??`ui-target:${commandKey}:${draft?.categoryId??'new'}`}/>
 {#if target}<input type="hidden" name="category_id" value={target.categoryId}/>{:else}<label>Category<select name="category_id" required value={draft?String(draft.categoryId):''}><option value="" disabled>Choose a category</option>{#each categories as c}<option value={String(c.id)}>{c.name}</option>{/each}</select></label>{/if}
 <label>Target amount<input name="amount" inputmode="decimal" required value={inputAmount(target?.amountCents??draft?.amountCents)} placeholder="0.00"/></label>
 <label>Cadence<select name="cadence" bind:value={cadence}><option value="monthly">Monthly</option><option value="weekly">Weekly</option><option value="annual">Annual</option><option value="irregular">Custom due date / balance</option></select></label>
 <label>Goal behavior<select name="behavior" bind:value={behavior}><option value="set_aside">Set aside a new amount</option><option value="refill">Refill to the target</option><option value="balance">Reach a balance</option></select></label>
 <label>Starts<input type="date" name="start_date" required value={target?.startDate??`${month}-01`}/></label>
 <label>Version effective month<input type="month" name="effective_month" required value={month}/></label>
 {#if cadence==='weekly'}<label>Weekly day<select name="weekday" required value={target?.weekday===undefined?'':String(target.weekday)}><option value="" disabled>Choose a day</option>{#each ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as day,i}<option value={String(i)}>{day}</option>{/each}</select></label>{/if}
 {#if cadence==='annual'||cadence==='irregular'}<label>Due date{#if cadence==='irregular'&&behavior==='balance'} (optional){/if}<input type="date" name="due_date" value={target?.dueDate??''} required={cadence==='annual'||behavior!=='balance'}/></label>{/if}
 {#if cadence==='irregular'}<label>Repeat every N months (optional)<input name="repeat_months" type="number" min="1" max="1200" step="1" value={target?.repeatMonths??''} placeholder="No repeat"/></label>{/if}
 <p class="target-help">{behavior==='refill'?'Refill covers what was missing at the start of the cycle. Spending within that cycle does not create a new refill requirement.':behavior==='balance'?'Balance progress uses the current category balance. Spending can increase what is needed.':'Set aside measures new contributions for the cycle, separately from spending.'} {cadence==='weekly'?'The monthly plan counts the chosen weekday only on or after the start date.':cadence==='annual'?'The due date repeats annually.':cadence==='monthly'?'Monthly goals use the calendar month; payment dates remain separate in scheduled activity.':'Leave repeat blank for a one-time goal.'} Editing a target never assigns cash. Earlier effective versions remain in history.</p>
 <button class="product-button primary">Save target</button>
</form>
{#if target}<details class="archive-target"><summary>Remove this target version</summary><p>Remove from the effective month below. Earlier history and any later scheduled version are preserved; no cash is moved.</p><form method="POST" action={`?/archiveTarget&month=${month}`} data-budget-command="archiveTarget"><input type="hidden" name="revision" value={revision}/><input type="hidden" name="key" value={`${commandKey}:archive:${target.categoryId}`}/><input type="hidden" name="target_id" value={target.id}/><label>Effective month<input name="effective_month" type="month" required value={month}/></label><button class="product-button">Remove target version</button></form></details>{/if}
<style>.target-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:18px 22px}.target-form label,.archive-target label{display:flex;flex-direction:column;gap:6px;font-size:13px;color:var(--muted-foreground);min-width:0}.target-form input,.target-form select,.archive-target input{min-height:44px;width:100%;min-width:0;padding:8px 10px;border:1px solid var(--input);border-radius:var(--radius);background:var(--surface);color:var(--foreground)}.target-help{grid-column:1/-1;font-size:12px;line-height:1.6;color:var(--muted-foreground)}.target-form button{justify-self:start;min-height:44px}.archive-target{margin:0 22px 20px;font-size:12px;color:var(--muted-foreground)}.archive-target summary{cursor:pointer;min-height:44px;align-content:center}.archive-target form{display:flex;flex-wrap:wrap;align-items:end;gap:12px}.archive-target p{margin-bottom:12px}@media(max-width:560px){.target-form{grid-template-columns:1fr}}</style>
